code:
module pedestrian_signal (
    input clk,
    input resetn,
    output reg walk,
    output reg dont_walk);

    parameter WALK = 0, DONT_WALK = 1;
    reg state, next_state;

    always @(posedge clk) begin
        if (~resetn) state <= DONT_WALK;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            WALK: next_state = DONT_WALK;
            DONT_WALK: next_state = WALK;
            default: next_state = DONT_WALK;
        endcase
    end

    always @(state) begin
        case (state)
            WALK: begin
                walk = 1;
                dont_walk = 0;
            end
            DONT_WALK: begin
                walk = 0;
                dont_walk = 1;
            end
            default: begin
                walk = 0;
                dont_walk = 0;
            end
        endcase
    end
endmodule

