module top_module(
    input clk, 
    input rst, 

    input native_empty,
    input [8:0]native_dout, 
    output native_rd_en,

    output [7:0] axis_tdata,
    output axis_tlast,
    output axis_tvalid,
    input axis_tready
);reg [1:0] counter = 0;
reg zero_padding = 0;

always @(posedge clk or posedge rst) begin
    if (rst) counter <= 0;
    else if (native_rd_en)
        counter <= counter + 1;
    if (rst) zero_padding <= 0;
    else if (counter == 3) zero_padding <= 0;
    else if (axis_tlast) zero_padding <= 1;
end
assign axis_tdata = native_dout[8:1];
assign axis_tlast = native_dout[0] && axis_tvalid;
assign axis_tvalid = ~native_empty && ~zero_padding;
assign native_rd_en = axis_tvalid && axis_tready || zero_padding;endmodule

module top_module(
    input clk,
    input run_game,
    output compute,
	 output hold
    );reg compute_reg = 0;
	 reg [2:0] counter = 0;
	 reg hold_reg = 0;

	 always @(posedge clk)
	 begin
		if(run_game == 1)
		begin
			hold_reg = 1;
			counter = counter + 1;
			if(counter == 3'b101)
			begin
				compute_reg = 1;
				counter = 0;
			end
		end
		else
		begin
			compute_reg = 0;
			counter = 0;
			hold_reg = 0;
		end
	 end

	 assign compute = compute_reg;
	 assign hold = hold_reg;

endmodule

