module top_module(
    input clk,
    input reset,
    input [31:0] x,
    output reg [15:0] y,
    output reg rdy
);reg signed [32:0] y0, y1, y_next;
    reg signed [63:0] x_fixed, y_fixed;
    reg [5:0] count;

    always @(posedge clk) begin
        if (reset) begin
            y0 <= 0;
            y1 <= 0;
            y_next <= 0;
            x_fixed <= 0;
            y_fixed <= 0;
            count <= 0;
            rdy <= 0;
        end else begin
            if (count == 0) begin
                x_fixed <= {x, 16'b0};
                y_fixed <= {y1, 16'b0};
                y0 <= y1;
                y_next <= (y_fixed + (x_fixed / y_fixed)) >> 1;
                count <= 1;
            end else begin
                y0 <= y_next;
                y_fixed <= {y0, 16'b0};
                y_next <= (y_fixed + (x_fixed / y_fixed)) >> 1;
                // Replacing abs function with conditional logic
                if ((y_next - y0) < 0 ? -(y_next - y0) : (y_next - y0) <= 1) begin
                    y <= y_next[32:17];
                    rdy <= 1;
                end
            end
        end
    end

endmodule

