	sdram_data
);parameter	W_IDLE		= 4'd0;		
	parameter	W_ACTIVE	= 4'd1;		
	parameter	W_TRCD		= 4'd2;		
	parameter	W_REF		= 4'd3;		
	parameter	W_RC		= 4'd4;		
	parameter	W_READ		= 4'd5;		
