	parameter	W_WRITE		= 4'd8;		
	parameter	W_PRECH		= 4'd9;		
	parameter	W_TRP		= 4'd10;	
	parameter	W_BSTOP		= 4'd11;	
	parameter	W_CHGACT	= 4'd12;	
	parameter	W_TRPACT	= 4'd13;	


	input 			clk;
	input 			rst_n;
	input[4:0] 		work_st;
	input[15:0]		cnt_work;
	input[15:0]		wr_sdram_data;
	inout[15:0]		sdram_data;


	reg				wr_sdram_flag;
	assign sdram_data = wr_sdram_flag ? wr_sdram_data : 16'bzzzz_zzzz_zzzz_zzzz;

	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			wr_sdram_flag   <= 0;
		end

		else if(work_st==W_WRITE)begin   
			wr_sdram_flag	<= 1;
		end

		else begin
			wr_sdram_flag   <= 0;
		end
	end




endmodule

