		lcd_x_q <= 0;
		lcd_y_q <= 0;
		lcd_data_q <= 0;
		lcd_hsync_q <= 0;
		lcd_vsync_q <= 0;
		lcd_de_q <= 0;
	end
	else begin
		lcd_hsync_q <= lcd_hsync_i;
		lcd_vsync_q <= lcd_vsync_i;
		lcd_de_q <= lcd_de_i;

		if (lcd_de_i) begin
			lcd_data_q <= lcd_data_i;
		end else begin
			lcd_data_q <= 0;
		end

		if (lcd_vsync_end) begin
			lcd_y_q <= 0;
		end else begin
			if (lcd_hsync_end) begin
				lcd_y_q <= lcd_y_q + 12'h1;
			end
		end

		if (lcd_hsync_end) begin
			lcd_x_q <= 0;
		end else begin
			if (lcd_de_q) begin
				lcd_x_q <= lcd_x_q + 12'h1;
			end
		end
	end
end

endmodule

