module top_module(
    input clk,
    input resetn,
    input s_sclk,
    input s_sdo,
    input s_sdo_t,
    input [2:0] m_sdi,
    input [3:0] s_cs,
    output reg data_ready
);localparam IDLE_TIMEOUT = 8; // Set to default value of 8

reg [$clog2(IDLE_TIMEOUT)-1:0] counter = IDLE_TIMEOUT;
reg [2:0] sdi_d = 'h00;

assign m_sclk = s_sclk;
assign m_sdo = s_sdo;
assign m_sdo_t = s_sdo_t;
assign s_sdi = m_sdi;
assign m_cs = s_cs;

always @(posedge clk) begin
    if (resetn == 1'b0) begin
        counter <= IDLE_TIMEOUT;
    end else begin
        if (s_cs[0] == 1'b0 && s_cs[3:1] == 3'b000 && s_sdo_t == 1'bZ) begin // Fixed order of part select
            if (counter != 'h00)
                counter <= counter - 1'b1;
        end else begin
            counter <= IDLE_TIMEOUT;
        end
    end
end

always @(posedge clk) begin
    /* The data ready signal is fully asynchronous */
    sdi_d <= {sdi_d[1:0], m_sdi};
end

always @(posedge clk) begin
    if (counter == 'h00 && sdi_d[2] == 1'b0) begin
        data_ready <= 1'b1;
    end else begin
        data_ready <= 1'b0;
    end
end

endmodule

