Design a programmable counter module that operates based on a clock signal (CCK) and various control signals. This module can be cleared asynchronously (NCCLR), enabled (NCCKEN), and loaded with an initial value (NCLOAD) from an 8-bit input (DATA). It also incorporates a clock divider (CLK_DIVIDER) to regulate the counting frequency. When enabled, the counter increments the output (QDATA) every time the divider countdown reaches one, allowing for count scaling. Initially, the counter is set to zero but can be loaded with a specified value upon receiving the load signal. The module is designed for applications where precise control over counting intervals is needed.
module top_module(  input [7:0] DATA, input NCCLR, input NCCKEN, input CCK,
                     input NCLOAD, input RCK, input [7:0] CLK_DIVIDER, output [7:0] QDATA);

code:
module top_module(  input [7:0] DATA, input NCCLR, input NCCKEN, input CCK,
                     input NCLOAD, input RCK, input [7:0] CLK_DIVIDER, output [7:0] QDATA);parameter CLK_DIVIDER_WIDTH = 8;

    reg [CLK_DIVIDER_WIDTH-1:0] _icounter;
    reg [7:0] _divider_counter;
    reg _count_enable;

    assign QDATA = _icounter;

    initial begin
        _icounter = {(CLK_DIVIDER_WIDTH){1'b0}};
        _divider_counter = {(8){1'b0}};
        _count_enable = 1'b0;
    end

    always @(posedge CCK, negedge NCCKEN, negedge NCCLR) begin
        if (~NCCKEN) begin
            if (~NCCLR) begin
                _icounter = 8'h0;
                _divider_counter = CLK_DIVIDER;
                _count_enable = 1'b0;
            end
            else if (~NCLOAD) begin
                _icounter = DATA;
                _divider_counter = CLK_DIVIDER;
                _count_enable = 1'b0;
            end
            else begin
                if (_count_enable) begin
                    if (_divider_counter == 8'h1) begin
                        _icounter =  _icounter + 1;
                        _divider_counter = CLK_DIVIDER;
                    end
                    else begin
                        _divider_counter = _divider_counter - 1;
                    end
                end
                else begin
                    _divider_counter = CLK_DIVIDER;
                    _count_enable = 1'b1;
                end
            end
        end
    end

endmodule

