  begin 
  if(!rst) begin 
  game_status <= START; 
  clk_cnt <= 0; 
  die_flash <= 1; 
  restart <= 0; 
  end 
  else begin 
  case(game_status) 
  RESTART:begin 
  if(clk_cnt <= 5) begin 
