  end 
  PLAY:begin 
  if(hit_wall | hit_body) 
  game_status <= DIE; 
  else 
  game_status <= PLAY; 
  end 
  DIE:begin 
  die_flash <= 1; 
  clk_cnt <= 0; 
  game_status <= RESTART; 
  end 
  endcase 
  end 
  end 
 endmodule

