description:
Design a PWM (Pulse Width Modulation) LED controller that generates four independent PWM signals to control the brightness of four LEDs based on a clock input. Each LED is driven by a different duty cycle: the first LED has a duty cycle of 4, the second 16, the third 64, and the fourth is driven continuously on with a duty cycle of 255. The module utilizes four separate counters that increment with each clock cycle to compare against predefined duty cycle values, effectively determining the ON/OFF state of each corresponding LED output.
module top_module(
    clk,
    led
);

code:
module top_module(
    clk,
    led
);input clk;
output [3:0] led;

reg [3:0] led_i; // Change from wire to reg to allow assignment
reg [7:0] pwm0_0_1_counter = 0;
reg [7:0] pwm1_0_counter = 0;
reg [7:0] pwm2_counter = 0;
reg [7:0] pwm3_counter = 0;

assign led = led_i;

wire [7:0] pwm0_0_1_dutyCount;
assign pwm0_0_1_dutyCount = 8'd4;

wire [7:0] pwm1_0_dutyCount;
assign pwm1_0_dutyCount = 8'd16;

wire [7:0] pwm2_dutyCount;
assign pwm2_dutyCount = 8'd64;

wire [7:0] pwm3_dutyCount;
assign pwm3_dutyCount = 8'd255;

always @(posedge clk) begin
    pwm0_0_1_counter <= (pwm0_0_1_counter + 1);
    led_i[0] <= (pwm0_0_1_counter < pwm0_0_1_dutyCount);
end

always @(posedge clk) begin
    pwm1_0_counter <= (pwm1_0_counter + 1);
    led_i[1] <= (pwm1_0_counter < pwm1_0_dutyCount);
end

always @(posedge clk) begin
    pwm2_counter <= (pwm2_counter + 1);
    led_i[2] <= (pwm2_counter < pwm2_dutyCount);
end

always @(posedge clk) begin
    pwm3_counter <= (pwm3_counter + 1);
    led_i[3] <= (pwm3_counter < pwm3_dutyCount);
end

endmodule

