module pedestrian_crossing (
	input clk,
	input resetn,
	input pedestrian_request,
	output reg light);

	parameter DONT_WALK=0, WALK=1;
	reg state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= DONT_WALK;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == next_state) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			DONT_WALK: next_state = pedestrian_request ? WALK : DONT_WALK;
			WALK: next_state = (counter == 4'b1111) ? DONT_WALK : WALK;
			default: next_state = DONT_WALK;
		endcase
	end

	always @(state) begin
		case (state)
			DONT_WALK: light = 0;
			WALK: light = 1;
			default: light = 0;
		endcase
	end
endmodule

