module top_module(
    input wire clk,
    input wire reset,
    input wire [4:0] binary_num,
    output reg is_lt16,
    output reg [2:0] count_zeros,
    output reg is_palindrome
);

    integer i;

    always @(posedge clk) begin
        if (reset) begin
            is_lt16 <= 0;
            count_zeros <= 0;
            is_palindrome <= 0;
        end else begin
            // Check if less than 16
