module traffic_light (
	input clk,
	input resetn,
	output reg [1:0] light);

	parameter RED=2'b00, GREEN=2'b10, YELLOW=2'b01;
	reg [1:0] state, next_state;
	reg [2:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= RED;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == next_state) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			RED: next_state = (counter == 3'b100) ? GREEN : RED;
			GREEN: next_state = (counter == 3'b100) ? YELLOW : GREEN;
			YELLOW: next_state = (counter == 3'b100) ? RED : YELLOW;
			default: next_state = RED;
		endcase
	end

	always @(state) begin
		case (state)
			RED: light = 2'b00;
			GREEN: light = 2'b10;
			YELLOW: light = 2'b01;
			default: light = 2'b00;
		endcase
	end
endmodule

module top_module(
  input clk,
  input reset,
  input A,
  input B,
  output reg C
);parameter S0 = 1'b0;
  parameter S1 = 1'b1;

  reg state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      C <= 1'b0;
    end
    else begin
      state <= next_state;
      case (state)
        S0: begin
          if (A) begin
            next_state <= S1;
          end
          else begin
            next_state <= S0;
          end
          C <= 1'b0;
        end
        S1: begin
          if (A) begin
            next_state <= S1;
          end
          else begin
            next_state <= S0;
          end
          if (C && !B) begin
            C <= 1'b0;
          end
          else if (A && !B) begin
            C <= 1'b0;
          end
          else if (A && B) begin
            C <= 1'b1;
          end
        end
      endcase
    end
  end

endmodule

