module top_module(
    input wire rclk, wclk, rrst_n, wrst_n, rinc, winc,
    input wire [7:0] din,
    output wire [7:0] dout,
    output reg rempty, wfull
);parameter DEPTH = 16;
parameter ADDR_WIDTH = $clog2(DEPTH);

reg [ADDR_WIDTH-1:0] rptr, wptr;
reg [7:0] memory [DEPTH-1:0];

wire [ADDR_WIDTH-1:0] gray_rptr, gray_wptr;
assign gray_rptr = rptr ^ (rptr >> 1);
assign gray_wptr = wptr ^ (wptr >> 1);

assign dout = memory[gray_rptr];

always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
        rempty <= 1'b1;
        rptr <= 0;
    end else if (rinc && !rempty) begin
        rptr <= gray_rptr + 1;
        rempty <= (gray_wptr == gray_rptr + 1);
    end
end

always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
        wptr <= 0;
        wfull <= 1'b0;
    end else if (winc && !wfull) begin
        wptr <= gray_wptr + 1;
        memory[gray_wptr] <= din;
        wfull <= (gray_wptr == gray_rptr);
    end
end

endmodule

