module top_module(
    input clk,
    input rst,
    input enable,
    input [7:0] voltage,
    output reg vdd,
    output reg vss
);// Constants
localparam MAX_VOLTAGE = 8'd255;
localparam MIN_VOLTAGE = 8'd0;
localparam MAX_LEVEL = 1'b1;
localparam MIN_LEVEL = 1'b0;
localparam MAX_VDD = 8'd127;
localparam MAX_VSS = 8'd128;

// Variables
reg [7:0] vdd_voltage;
reg [7:0] vss_voltage;

// Reset
always @(posedge clk) begin
    if (rst) begin
        vdd <= MIN_LEVEL;
        vss <= MIN_LEVEL;
        vdd_voltage <= MIN_VOLTAGE;
        vss_voltage <= MAX_VOLTAGE;
    end
end

// Voltage control
always @(posedge clk) begin
    if (enable) begin
        // Set VDD voltage level
        if (voltage > MAX_VDD) begin
            vdd_voltage <= MAX_VDD;
        end else begin
            vdd_voltage <= voltage;
        end

        // Set VSS voltage level
        if (voltage > MAX_VSS) begin
            vss_voltage <= MAX_VSS;
        end else begin
            vss_voltage <= ~voltage;
        end
    end else begin
        vdd_voltage <= MIN_VOLTAGE;
        vss_voltage <= MAX_VOLTAGE;
    end
end

// Voltage supply
always @(posedge clk) begin
    if (vdd_voltage > MAX_VDD) begin
        vdd <= MAX_LEVEL;
    end else if (vdd_voltage < MIN_VOLTAGE) begin
        vdd <= MIN_LEVEL;
    end else begin
        vdd <= vdd_voltage[MAX_VDD-1];
    end

    if (vss_voltage > MAX_VOLTAGE) begin
        vss <= MAX_LEVEL;
    end else if (vss_voltage < MIN_VOLTAGE) begin // Changed from MIN_VSS to MIN_VOLTAGE
        vss <= MIN_LEVEL;
    end else begin
        vss <= vss_voltage[MAX_VOLTAGE-1];
    end
end

endmodule

