module top_module(
  input                clk,              // Clock input for Johnson counter
  input                reset,            // Synchronous active-high reset input for Johnson counter
  input [49:0]         in,               // 50-inputs for the combinational circuit
  input [49:0]         count_value,      // Value to compare counter with
  output reg           out_nand,         // Output of 50-input NAND gate in combinational circuit
  output reg           out_nor,          // Output of 50-input NOR gate in combinational circuit
  output reg           out_signal        // Output of functional module
);reg [63:0] counter;
  reg [5:0] johnson_counter;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      counter <= 0;
      johnson_counter <= 6'b111111;
    end
    else begin
      counter <= counter + 1;
      johnson_counter <= {johnson_counter[4:0], ~johnson_counter[5]};
    end
  end

  assign out_nand = ~(&in);
  assign out_nor = ~(|in);

  always @(posedge clk) begin
    if (counter == count_value && johnson_counter == 6'b000000) begin
      out_signal <= 1'b1;
    end
    else begin
      out_signal <= 1'b0;
    end
  end

endmodule

module top_module(
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [4:0] out
);reg [3:0] mux_out;
reg parity;

always @* begin
    case (sel)
        3'b000: mux_out = {data1, data0};
        3'b001: mux_out = {data3, data2};
        3'b010: mux_out = {data5, data4};
        default: mux_out = 4'b0;
    endcase

    parity = mux_out[0] ^ mux_out[1] ^ mux_out[2] ^ mux_out[3];
    out = {mux_out, parity};
end

endmodule

